export interface CountryRings {
  id: string;
  rings: number[][];
}

function decodeRings(): CountryRings[] {
  const bin = atob(COORDS_B64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  const i16 = (off: number): number => {
    const v = bytes[off]! | (bytes[off + 1]! << 8);
    return v > 32767 ? v - 65536 : v;
  };
  let off = 0;
  return META.map(([id, counts]) => ({
    id,
    rings: counts.map((n) => {
      const ring = new Array<number>(n * 2);
      for (let i = 0; i < n; i++) {
        ring[i * 2] = i16(off) / 100;
        ring[i * 2 + 1] = i16(off + 2) / 100;
        off += 4;
      }
      return ring;
    }),
  }));
}

export const COUNTRY_RINGS: CountryRings[] = decodeRings();
